def calc(a, i=0):
    if i >= len(a):
        return 0
    if a[i] % 2 == 0:
        return a[i] + calc(a, i + 1)
    return calc(a, i + 1)
a = [3, 4, 2, 5, 6]
x = calc(a)
y = calc(a, 3)

