Giá trị cuối của x là bao nhiêu?

a = [2, -1, 0, 3]
x = y = 0
for v in a:
    try:
        if v < 0:
            raise ValueError("âm")
        x += 6 // v
    except ValueError:
        y += 1
    except ZeroDivisionError:
        y += 2
    else:
        y += 3

